import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group, Color } = ctx.THREE;
  const root = new Group();
  root.name = 'pricing-card-3-label';

  const resources = [];
  const timelines = [];
  let disposed = false;

  const surfaceMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true
  });

  const uvNode = uv();
  const vertical = uvNode.y;

  const surface = vec3(0.043, 0.043, 0.063);
  const ink = vec3(0.086, 0.086, 0.114);
  const paper = vec3(0.910, 0.925, 0.949);
  const accent = vec3(1.0, 0.165, 0.220);

  const verticalGradient = mix(
    mix(surface, ink, smoothstep(0.0, 0.58, vertical)),
    vec3(0.125, 0.125, 0.155),
    smoothstep(0.58, 1.0, vertical)
  );

  const grain = fract(
    sin(
      uvNode.x.mul(91.7).add(
        uvNode.y.mul(173.1)
      )
    ).mul(43758.5)
  );

  const grainSurface = mix(
    verticalGradient,
    verticalGradient.add(vec3(0.018, 0.018, 0.022)),
    grain.mul(0.22)
  );

  const signalWash = smoothstep(0.76, 0.98, vertical).mul(0.08);
  surfaceMaterial.colorNode = mix(grainSurface, accent, signalWash);

  const cardGeometry = new PlaneGeometry(2.55, 1.48, 1, 1);
  const card = new Mesh(cardGeometry, surfaceMaterial);
  card.name = 'engineered-gradient-surface';
  card.position.z = 0;
  root.add(card);

  resources.push(cardGeometry, surfaceMaterial);

  const insetMaterial = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    transparent: true,
    opacity: 0.92,
    depthWrite: false
  });

  const insetGeometry = new PlaneGeometry(0.035, 0.84, 1, 1);
  const inset = new Mesh(insetGeometry, insetMaterial);
  inset.name = 'signal-red-accent';
  inset.position.set(-1.035, -0.015, 0.035);
  root.add(inset);

  resources.push(insetGeometry, insetMaterial);

  const innerMaterial = new MeshBasicNodeMaterial({
    color: new Color('#16161d'),
    transparent: true,
    opacity: 0.72,
    depthWrite: false
  });

  const innerGeometry = new PlaneGeometry(2.18, 0.018, 1, 1);
  const innerRule = new Mesh(innerGeometry, innerMaterial);
  innerRule.name = 'machined-inner-rule';
  innerRule.position.set(0.08, -0.48, 0.035);
  root.add(innerRule);

  resources.push(innerGeometry, innerMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textIndex = 0;

  for (const item of items) {
    const content = typeof item?.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 440,
      letterSpacingPx: 0
    });

    textObject.name = item.role || `text-${textIndex}`;
    textObject.position.set(0.08, -0.04 - textIndex * 0.28, 0.07);
    root.add(textObject);
    textIndex += 1;
  }

  const imageUrl = config.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    const imageMaterial = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0.045,
      depthWrite: false
    });

    const imageGeometry = new PlaneGeometry(2.55, 1.48, 1, 1);
    const imageOverlay = new Mesh(imageGeometry, imageMaterial);
    imageOverlay.name = 'asset-grain-overlay';
    imageOverlay.position.z = 0.022;
    root.add(imageOverlay);

    resources.push(imageGeometry, imageMaterial);

    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  const entrance = gsap.timeline({ paused: false });
  entrance.fromTo(
    root.children,
    { opacity: 0, y: 0.2 },
    {
      opacity: 1,
      y: 0,
      duration: 0.5,
      stagger: 0.08,
      ease: 'power2.out'
    }
  );
  timelines.push(entrance);

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;

    const result = handler(root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) resources.push(result);
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const resource of resources) {
      if (resource?.cleanup && typeof resource.cleanup === 'function') {
        resource.cleanup();
      } else if (resource?.dispose && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    root.clear();
  };

  return root;
}
